        c = Concrete()
        self.assertEqual(handler(c), "default")

        AlphaBase.register(Concrete)
        BetaBase.register(Concrete)

        with self.assertRaises(RuntimeError) as ctx:
            handler(c)
        self.assertIs(type(ctx.exception), RuntimeError)
